insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.1', array['3.1']::text[], 'convention', 'Partial charges explain dipole and ion-dipole strength', 'Judge the strength and orientation dependence of dipole-dipole and ion-dipole forces by the sign of the partial charges behind the molecular dipole moment and how those charges interact with an ion or an adjacent dipole.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r2-001; ced=3.1.A.3: "considering the sign of the partial charges responsible for the molecular dipole moment, and how these partial charges interact with an ion or with an adjacent dipole"')
