insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.1', array['3.1']::text[], 'convention', 'Polar vs. nonpolar molecules of similar size', 'Interactions between polar molecules are typically greater than those between nonpolar molecules of comparable size, because dipole-dipole interactions act in addition to London dispersion forces.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r2-002; ced=3.1.A.2: "Interactions between polar molecules are typically greater than those between nonpolar molecules of comparable size because these interactions act in addition to London dispersion forces."')
