insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.2', array['3.2']::text[], 'list_sequence', 'Four types of solids and their properties', 'Ionic, covalent network, molecular, and metallic solids, each with characteristic particle-level structure and macroscopic properties.', '[{"label": "Ionic", "meaning": "Strong ion-ion interactions: low vapor pressure, high melting and boiling points, brittle (like charges repel when layers slide); conducts only when ions are mobile (molten or dissolved)."}, {"label": "Covalent network", "meaning": "Atoms covalently bonded in a 3-D network (diamond) or layers (graphite), only from nonmetals/metalloids; high melting points; 3-D networks rigid and hard; graphite soft because layers slide."}, {"label": "Molecular", "meaning": "Discrete covalently bonded molecules held by relatively weak intermolecular forces: low melting point, do not conduct because valence electrons are held in bonds and lone pairs."}, {"label": "Metallic", "meaning": "Free valence electrons: good conductors of electricity and heat, malleable and ductile; interstitial alloys are more rigid (less malleable/ductile) but still conduct."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r1-009; ced=3.2.A.3-3.2.A.6')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.2', array['3.2']::text[], 'convention', 'IMF strength vs. vapor pressure, boiling point, melting point', 'Vapor pressure and boiling point are directly related to intermolecular force strength because the interactions are completely overcome in vaporization, while melting points correlate more subtly because the interactions are only rearranged.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r1-008; ced=3.2.A.1 vapor pressure and boiling point are directly related to the strength of those interactions')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.3', array['3.3']::text[], 'vocabulary', 'Crystalline vs. amorphous solids', 'Crystalline solids have particles arranged in a regular three-dimensional structure, while amorphous solids have no regular, orderly arrangement of particles.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r1-010; ced=3.3.A.1 crystalline, where the particles are arranged in a regular three-dimensional structure, or ... amorphous')
