insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 3, '3.3', array['3.3']::text[], 'diagram', 'Particulate model of solid, liquid, and gas', 'A particulate-level model shows how particle arrangement, spacing, and motion differ among the solid, liquid, and gas phases.', '[{"label": "Solid (crystalline or amorphous)", "meaning": "Particles are in close contact. They are in a regular 3-D arrangement if crystalline and an irregular one if amorphous. Motion is limited, with no overall translation of particles relative to each other."}, {"label": "Liquid", "meaning": "Particles are in close contact, similar in molar volume to the solid, and are continually moving and colliding. Their arrangement and movement depend on the nature and strength of the forces between them."}, {"label": "Gas", "meaning": "Particles are in constant motion with minimal effects from forces between them. Collision frequency and average spacing depend on temperature, pressure, and volume. The gas has neither a definite volume nor a definite shape."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u3-r2-007; ced=3.3.A.1-3.3.A.4: "Represent the differences between solid, liquid, and gas phases using a particulate-level model"')
